fun flutterMinJavaMajor(): Int {
    val cls = Class.forName("com.flutter.gradle.DependencyVersionChecker")
    val instance = cls.getField("INSTANCE").get(null)
    // Kotlin `internal` compiles to a public JVM getter with a `$<module>` suffix.
    // Match by prefix so an upstream module rename does not break us.
    val getter = cls.methods.firstOrNull {
